import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.BAQ5ZYJQ.js";const k=JSON.parse('{"title":"Automatic installations","description":"","frontmatter":{},"headers":[],"relativePath":"guide/upkeep.md","filePath":"guide/upkeep.md","lastUpdated":1795160929000}'),n={name:"guide/upkeep.md"};function h(o,e,r,d,l,p){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="automatic-installations" tabindex="-1">Automatic installations <a class="header-anchor" href="#automatic-installations" aria-label="Permalink to &quot;Automatic installations&quot;">​</a></h1><p>An environment is installed where it runs, from what it declares, and kept current: nothing to do by hand on the other machine, not even installing errand ( it brings itself, and a Python when there is none ). The first command that needs a conda env, a venv or an image builds it there; the next one after a change to its declaration updates it.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> envs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # what is declared, and what state it is in</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # build or update now, and nothing else</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gpu</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cluster</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # those two</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # from scratch</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # say what it would run, and run nothing</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-setup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> …</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # skip the check for this command</span></span></code></pre></div><p>A layer says what it is made from: a Python version, channels, a <code>requirements.txt</code>, a <code>.def</code> or a <code>Dockerfile</code>, a pip list. Before a command, errand compares a fingerprint of that with what it last built, and brings the environment up to date when they differ: a new pip package, an edited recipe, a changed requirements file.</p><p>You do not have to act on <code>stale</code> or <code>not built</code> in <code>errand envs</code>. The next command that needs the environment builds it first, and <code>errand shell</code> does too.</p><h2 id="what-is-already-there-is-adopted-not-rebuilt" tabindex="-1">What is already there is adopted, not rebuilt <a class="header-anchor" href="#what-is-already-there-is-adopted-not-rebuilt" aria-label="Permalink to &quot;What is already there is adopted, not rebuilt&quot;">​</a></h2><p>The first time errand meets an environment, it has no record of how it was built, so every layer looks out of date. Acting on that would mean recreating, on somebody&#39;s first command, an environment that has worked for months.</p><p>So <strong>an environment that is there and was never seen before is recorded as <code>adopted</code></strong>, and left as it is. Only a declaration that has <em>changed</em> since a record errand wrote itself is a reason to touch anything. <code>errand setup --force</code> is how you ask for the rest.</p><p>The one exception is an image, which a build cannot harm: found older than its recipe, it is rebuilt. Anything else older than what it declares is adopted, with a warning.</p><div class="danger custom-block"><p class="custom-block-title">Why this matters</p><p><code>micromamba create -n x</code> on an existing <code>x</code> is not a no-op and not an update: it resolves the named specs into it, and <code>python=3.13</code> over a 3.14 environment takes every package installed for 3.14 out with it. An environment somebody works in must never be damaged by a declaration being read for the first time.</p></div><h2 id="what-errand-remembers" tabindex="-1">What errand remembers <a class="header-anchor" href="#what-errand-remembers" aria-label="Permalink to &quot;What errand remembers&quot;">​</a></h2><p>A record lives on the machine that holds what was built, in its <code>errand-outputs/builds/records/</code> ( or under <code>builds_directory</code> ): one yaml per artefact, with the output of the last attempt beside it. Both are rewritten each time; there is no history. The yaml holds the fingerprint of the declaration and a stamp of the result: an image&#39;s date and size, a Docker image&#39;s id, a conda prefix&#39;s <code>conda-meta/history</code>, a venv&#39;s <code>site-packages</code>. An artefact whose stamp changed behind errand&#39;s back is adopted again.</p><h2 id="when-a-build-fails" tabindex="-1">When a build fails <a class="header-anchor" href="#when-a-build-fails" aria-label="Permalink to &quot;When a build fails&quot;">​</a></h2><p>A failed build stops the command, and is tried again by the next one, changed or not.</p><p><strong>An image is built aside</strong>, as <code>&lt;image&gt;.new</code>: the existing one stays whole, and <code>errand run --no-setup</code> can still use it. It is replaced once the new one is complete, and kept as <code>&lt;image&gt;.prev</code> until the next build. Conda environments and venvs cannot be moved once built, so they are updated in place: after a failure they may be half updated.</p><h2 id="what-stays-on-the-other-machine" tabindex="-1">What stays on the other machine <a class="header-anchor" href="#what-stays-on-the-other-machine" aria-label="Permalink to &quot;What stays on the other machine&quot;">​</a></h2><p>The push to another machine deletes what is only over there. What a layer builds in the project ( an image with its <code>.new</code>, <code>.prev</code> and <code>.part</code>, a uv environment ) is excluded by its exact path, for every environment of the project. Anything else that exists only over there goes at the next push, and errand prints what went. Keep what you put there by hand outside the project&#39;s copy, or declare it as a <a href="./sync#zones">zone</a>.</p><h2 id="where-an-image-gets-built" tabindex="-1">Where an image gets built <a class="header-anchor" href="#where-an-image-gets-built" aria-label="Permalink to &quot;Where an image gets built&quot;">​</a></h2><p>An image is built <strong>where it is used</strong>. With an <code>Ssh</code> layer in front, the recipe — a file here — is copied over, and <code>apptainer build</code> runs on that host, with <code>fakeroot</code> and <code>scratch</code> as declared:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Apptainer( </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">image</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;containers/cuda.sif&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">recipe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;containers/cuda.def&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">           fakeroot</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">scratch</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/scratch/me/apptainer&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> )</span></span></code></pre></div><p><code>fakeroot</code> builds without root on a host that allows it. <code>scratch</code> is a directory with room: apptainer unpacks whole layers, and the default <code>/tmp</code> is where a build dies halfway, out of space, on a shared machine. For a host without internet, see <a href="./layers/containers#a-cluster-without-internet"><code>build_on</code></a>.</p><p>This is also why <a href="./installing#no-dependencies">errand has no dependencies</a>: it has to work before any environment exists.</p><h2 id="when-something-breaks" tabindex="-1">When something breaks <a class="header-anchor" href="#when-something-breaks" aria-label="Permalink to &quot;When something breaks&quot;">​</a></h2><p><code>-v</code> prints every process errand starts, on stderr, before it starts: the probe that checks an environment exists, the ssh line, the image build, the scheduler submission, the errand that runs over there. Each comes with its directory, when it is not the current one, and the variables it is handed beyond errand&#39;s own. A command that fails says its exit code and how long it took.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lmo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./solve</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lmo</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  · $ ssh lmo &#39;$SHELL -ic &#39;&quot;&#39;&quot;&#39;cd /home/me/proj &amp;&amp; micromamba -n prj run true&#39;&quot;&#39;&quot;&#39;&#39;</span></span>
<span class="line"><span>  · ✗ exit 1 after 0.4 s: ssh lmo &#39;$SHELL -ic ...</span></span></code></pre></div><p>It crosses with the command: the errand over ssh, in a container or under a scheduler prints its own commands too. Probes that are otherwise silent keep their output, so a failed check says why. What the work itself starts is printed as well when errand runs it in its own process, an entry&#39;s <code>subprocess.run</code> for instance.</p><p>To look around by hand, <code>errand shell --env lmo</code> opens a shell in the same place, through the same layers. → <a href="./running#a-shell-in-an-environment-errand-shell">Running a command</a></p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p><a href="./tags">Choosing among environments (tags)</a>, for projects with many environments.</p>`,30)])])}const u=a(n,[["render",h]]);export{k as __pageData,u as default};
